2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the potential for a use-after-free condition when the per-cpu channel list was accessed in the interrupt routine while a channel was being deleted. If an interrupt occurred during the deletion process, it could lead to accessing a freed memory location, resulting in undefined behavior or crashes.

        Commit message:
        vmbus: use rcu for per-cpu channel list

The per-cpu channel list is now referred to in the interrupt
routine. This is mostly safe since the host will not normally generate
an interrupt when channel is being deleted but if it did then there
would be a use after free problem.

To solve, this use RCU protection on ther per-cpu list.

Fixes: 631e63a9f346 ("vmbus: change to per channel tasklet")

Signed-off-by: Stephen Hemminger <sthemmin@microsoft.com>
Signed-off-by: K. Y. Srinivasan <kys@microsoft.com>
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>  

        Patch:
          */
 static void vmbus_chan_sched(struct hv_per_cpu_context *hv_cpu)
 {
 	unsigned long *recv_int_page;
 	u32 maxbits, relid;

 	if (vmbus_proto_version < VERSION_WIN8) {
 		maxbits = MAX_NUM_CHANNELS_SUPPORTED;
 		recv_int_page = vmbus_connection.recv_int_page;
 	} else {
 		/*
 		 * When the host is win8 and beyond, the event page
 		 * can be directly checked to get the id of the channel
 		 * that has the interrupt pending.
 		 */
 		void *page_addr = hv_cpu->synic_event_page;
 		union hv_synic_event_flags *event
 			= (union hv_synic_event_flags *)page_addr +
 						 VMBUS_MESSAGE_SINT;

 		maxbits = HV_EVENT_FLAGS_COUNT;
 		recv_int_page = event->flags;
 	}

 	if (unlikely(!recv_int_page))
 		return;

 	for_each_set_bit(relid, recv_int_page, maxbits) {
 		struct vmbus_channel *channel;

 		if (!sync_test_and_clear_bit(relid, recv_int_page))
 			continue;

 		/* Special case - vmbus channel protocol msg */
 		if (relid == 0)
 			continue;

+		rcu_read_lock();
+
 		/* Find channel based on relid */
-		list_for_each_entry(channel, &hv_cpu->chan_list, percpu_list) {
+		list_for_each_entry_rcu(channel, &hv_cpu->chan_list, percpu_list) {
 			if (channel->offermsg.child_relid != relid)
 				continue;

 			switch (channel->callback_mode) {
 			case HV_CALL_ISR:
 				vmbus_channel_isr(channel);
 				break;

 			case HV_CALL_BATCHED:
 				hv_begin_read(&channel->inbound);
 				/* fallthrough */
 			case HV_CALL_DIRECT:
 				tasklet_schedule(&channel->callback_event);
 			}
 		}
+
+		rcu_read_unlock();
 	}
 }



